<section class="hero-row compact-hero"><div><span class="eyebrow">Organização</span><h2 class="page-heading">Categorias</h2><p class="page-subtitle">Classifique entradas e saídas para entender seus hábitos.</p></div></section>
<div class="catalog-layout"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Nova categoria</span><h3>Adicionar categoria</h3></div></div><form method="post" action="/categorias" class="inline-form"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><label class="field"><span>Nome</span><input type="text" name="name" placeholder="Ex.: Assinaturas" maxlength="120" required></label><label class="field"><span>Tipo</span><select name="type"><option value="expense">Despesa</option><option value="income">Receita</option></select></label><label class="field"><span>Cor</span><input type="color" name="color" value="#2563eb"></label><button class="button button-primary" type="submit">Adicionar</button></form></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Categorias disponíveis</span><h3><?= count($categories) ?> categorias</h3></div></div><div class="catalog-list"><?php foreach ($categories as $category): ?><div class="catalog-item"><span class="category-dot" style="background:<?= htmlspecialchars($category->color) ?>"></span><div><strong><?= htmlspecialchars($category->name) ?></strong><small><?= $category->type === 'income' ? 'Receita' : 'Despesa' ?><?= $category->user_id === null ? ' · padrão' : '' ?></small></div><span class="status-badge status-<?= $category->status ?>"><?= $category->status === 'active' ? 'Ativa' : 'Inativa' ?></span><?php if ($category->user_id !== null): ?><details class="action-menu"><summary>•••</summary><div class="action-popover"><form method="post" action="/categorias/<?= (int) $category->id ?>/toggle"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit"><?= $category->status === 'active' ? 'Desativar' : 'Ativar' ?></button></form><form method="post" action="/categorias/<?= (int) $category->id ?>/excluir" data-confirm="Excluir esta categoria?"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit" class="danger-text">Excluir</button></form></div></details><?php endif; ?></div><?php endforeach; ?></div></section></div>
